      head += '<span class="alloc-toolbar">';
      if (draft) head += '<span class="alloc-points">剩余 ' + Math.max(0, available - draft.spent) + '/' + available + '</span><button class="char-btn alloc-save" data-kind="skill">完成</button><button class="char-btn alloc-cancel" data-kind="skill">取消</button>';
      else head += '<span class="alloc-points">技能点 ' + available + '</span><button class="char-btn alloc-start" data-kind="skill">技能加点</button>';
