  async function migrateTalentSkillEntry(fromKind, toKind, name) {
    fromKind = String(fromKind || '');
    toKind = String(toKind || '');
    name = String(name || '');
    if (!name || !((fromKind === '天赋' && toKind === '技能') || (fromKind === '技能' && toKind === '天赋'))) return;
    try {
      var msgId = getCurrentMessageId();
      await updateVariablesWith(function (vars) {
        vars = vars || {};
        vars.stat_data = vars.stat_data || {};
        vars.stat_data['天赋与技能'] = vars.stat_data['天赋与技能'] || {};
        var root = vars.stat_data['天赋与技能'];
        root['天赋'] = root['天赋'] || {};
        root['技能'] = root['技能'] || {};
        var source = root[fromKind] || {};
        var target = root[toKind] || {};
        var entry = source[name];
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) entry = { '效果': textOf(entry) };
        entry = $.extend(true, {}, entry);
        if (fromKind === '天赋' && toKind === '技能') {
          if (entry['技能效果'] === undefined) entry['技能效果'] = textOf(entry['天赋效果'] || entry['效果']);
          if (entry['技能熟练度'] === undefined) entry['技能熟练度'] = '入门';
          if (entry['技能等级'] === undefined) entry['技能等级'] = 'Lv.1';
        } else {
          if (entry['天赋效果'] === undefined) entry['天赋效果'] = textOf(entry['技能效果'] || entry['效果']);
          if (entry['天赋稀有度'] === undefined) entry['天赋稀有度'] = '普通';
        }
        target[name] = mergeTalentSkillFields(target[name], entry);
        delete source[name];
        root[fromKind] = source;
        root[toKind] = target;
        return vars;
      }, { type: 'message', message_id: msgId });
      if (fromKind === '技能') {
        skillAllocDraft = null;
        $('.hud-container').removeClass('allocation-mode');
      }
      lastPopulateSignature = '';
      populate(Mvu.getMvuData({ type: 'message', message_id: msgId }), { force: true });
      toastr.info('已迁移：' + name + '（' + fromKind + '→' + toKind + '）');
    } catch (e) {
      toastr.error('迁移失败：' + (e && e.message || e));
    }
  }

