  function _statBars(v, keys) {
    var html = '<div class="mecha-section"><div class="mecha-section-title">状态</div>';
    var hadAny = false;
    keys.forEach(function (k) {
      if (!shouldRenderValue(v[k])) return;
      hadAny = true;
      var shown = displayValue(v[k], '--');
      var m = String(shown).match(/^(\d+)\s*\/\s*(\d+)/);
      var pct = m ? (parseInt(m[1], 10) / Math.max(1, parseInt(m[2], 10)) * 100) : 100;
      pct = Math.max(0, Math.min(100, pct));
      html += '<div class="stat-bar-row">';
      html += '<span class="stat-bar-label">' + k + '</span>';
      html += '<div class="stat-bar"><div class="stat-bar-fill" style="width:' + pct.toFixed(0) + '%;"></div></div>';
      html += '<span class="stat-bar-text">' + shown + '</span>';
      html += '</div>';
    });
    html += '</div>';
    return hadAny ? html : '';
  }
